"""Write the index table into adr/README.md from the ADR files' front matter. Generated: do not edit it by hand.

    uv run scripts/adr_index.py
"""
from lint_shape import ROOT, load_adrs

BEGIN = "<!-- BEGIN index: generated by scripts/adr_index.py, do not edit by hand -->"
END = "<!-- END index -->"


def render(adrs):
    rows = ["| Id | Decision | Status | Concerns | Capabilities |", "|---|---|---|---|---|"]
    for a in sorted(adrs, key=lambda a: a["id"]):
        rows.append(f"| [{a['id']}]({a['_file']}) | {a['_title']} | {a['status']} | {', '.join(a['concerns'])} | "
                    f"{', '.join(a['dpc'])} |")
    return "\n".join(rows)


def with_index(readme, adrs):
    head, rest = readme.split(BEGIN, 1)
    _, tail = rest.split(END, 1)
    return f"{head}{BEGIN}\n{render(adrs)}\n{END}{tail}"


if __name__ == "__main__":
    p = ROOT / "adr" / "README.md"
    p.write_text(with_index(p.read_text(), load_adrs()))
    print(f"wrote the index into adr/README.md ({len(load_adrs())} ADRs)")
